import { afterEach, expect, it } from 'vitest'
import { cleanup, fireEvent, render } from '@testing-library/react'
import '@testing-library/jest-dom/vitest'
import { App } from './App'
import { StatusBadge } from './StatusBadge'
import { SyncIndicator } from './SyncIndicator'

afterEach(cleanup)

it('renders compact and priority highlights immediately on each toggle', () => {
  const screen = render(<App />)
  const compact = screen.getByRole('button', { name: 'Compact' })
  const priority = screen.getByRole('button', { name: 'Priority only' })
  const panel = screen.getByRole('main')
  expect(compact).not.toHaveClass('is-active')
  expect(panel).not.toHaveClass('compact')
  expect(priority).not.toHaveClass('is-active')
  for (const enabled of [true, false, true]) {
    fireEvent.click(compact)
    fireEvent.click(priority)
    expect(compact).toHaveAttribute('aria-pressed', String(enabled))
    expect(priority).toHaveAttribute('aria-pressed', String(enabled))
    for (const button of [compact, priority]) {
      if (enabled) expect(button).toHaveClass('is-active')
      else expect(button).not.toHaveClass('is-active')
    }
    if (enabled) expect(panel).toHaveClass('compact')
    else expect(panel).not.toHaveClass('compact')
  }
})

it('renders folder and view highlights on initial render and selection', () => {
  const screen = render(<App />)
  const inbox = screen.getByRole('button', { name: /Inbox/ })
  const sent = screen.getByRole('button', { name: /Sent/ })
  const list = screen.getByRole('button', { name: 'List' })
  const preview = screen.getByRole('button', { name: 'Preview' })
  expect(inbox).toHaveClass('is-active')
  expect(sent).not.toHaveClass('is-active')
  expect(list).toHaveClass('is-active')
  expect(preview).not.toHaveClass('is-active')
  fireEvent.click(sent)
  fireEvent.click(preview)
  expect(sent).toHaveClass('is-active')
  expect(inbox).not.toHaveClass('is-active')
  expect(preview).toHaveClass('is-active')
  expect(list).not.toHaveClass('is-active')
  fireEvent.click(inbox)
  fireEvent.click(list)
  expect(inbox).toHaveClass('is-active')
  expect(sent).not.toHaveClass('is-active')
  expect(list).toHaveClass('is-active')
  expect(preview).not.toHaveClass('is-active')
})

it('renders search focus styling on focus and blur', () => {
  const screen = render(<App />)
  const search = screen.getByRole('searchbox')
  expect(search).not.toHaveClass('is-focused')
  fireEvent.focus(search)
  expect(search).toHaveClass('is-focused')
  fireEvent.blur(search)
  expect(search).not.toHaveClass('is-focused')
})

it('renders unread and sync styles from current props', () => {
  const screen = render(<><StatusBadge count={3} /><SyncIndicator online /></>)
  const badge = screen.getByText('3')
  const sync = screen.getByRole('status')
  expect(badge).toHaveClass('has-unread')
  expect(sync).toHaveClass('is-online')
  screen.rerender(<><StatusBadge count={0} /><SyncIndicator online={false} /></>)
  expect(badge).not.toHaveClass('has-unread')
  expect(sync).not.toHaveClass('is-online')
  expect(sync).toHaveTextContent('Offline')
  screen.rerender(<><StatusBadge count={3} /><SyncIndicator online /></>)
  expect(badge).toHaveClass('has-unread')
  expect(sync).toHaveClass('is-online')
})

